import{store,watch}from"@wordpress/interactivity";let state=store("core/router").state,isFirstRun=!0;watch(()=>{let t=state.url;isFirstRun?isFirstRun=!1:requestAnimationFrame(()=>{document.dispatchEvent(new CustomEvent("cmplz_router_navigated",{detail:{url:t}})),setTimeout(()=>{document.dispatchEvent(new CustomEvent("cmplz_router_navigated",{detail:{url:t}}))},100)})});